const tint = (s: string, c: HairColour) => {
  const t = HAIR_COLOURS.find((h) => h.id === c) ?? HAIR_COLOURS[0];
  return s.split("url(#hairGrad)").join(`url(#${t.grad})`).split("#3E241B").join(t.dark).split("#E2BC92").join(t.light);
};
/** The back and front hair layers for a given style and colour */
export function hairFor(style: HairStyle, colour: HairColour) {
  const h = STYLES[style] ?? STYLES.blowout;
  return { back: tint(hairLayer(h.back), colour), front: tint(hairLayer(h.front), colour) };
}

/* ── Fit helpers: trace Jess's own body outline so new clothes sit flush on her ── */
// Her left side as curves (the right side mirrors at x = 100), matching BODY_PARTS
const EDGE: number[][] = [[77, 112, 80, 140, 84, 165], [84, 165, 76, 185, 74, 205], [74, 205, 78, 265, 82, 320]];
/** x of her left body edge at height y */
const edgeL = (y: number) => {
  if (y <= 112) return 77 + (112 - y) * 0.25;
  for (const [x0, y0, cx, cy, x1, y1] of EDGE) if (y <= y1) {
    let lo = 0, hi = 1;
    for (let i = 0; i < 30; i++) { const t = (lo + hi) / 2, yy = (1 - t) * (1 - t) * y0 + 2 * t * (1 - t) * cy + t * t * y1; if (yy < y) lo = t; else hi = t; }
    const t = lo; return (1 - t) * (1 - t) * x0 + 2 * t * (1 - t) * cx + t * t * x1;
  }
  return 82;
};
const f1 = (n: number) => +n.toFixed(1);
const steps = (a: number, b: number) => { const s: number[] = []; for (let y = a + 4; y < b; y += 4) s.push(y); return s; };
const downL = (a: number, b: number, p: number) => steps(a, b).map((y) => `L${f1(edgeL(y) - p)} ${y}`).join(" ");
const upR = (a: number, b: number, p: number) => steps(a, b).reverse().map((y) => `L${f1(200 - edgeL(y) + p)} ${y}`).join(" ");
const upL = (a: number, b: number, p: number) => steps(a, b).reverse().map((y) => `L${f1(edgeL(y) - p)} ${y}`).join(" ");
const downR = (a: number, b: number, p: number) => steps(a, b).map((y) => `L${f1(200 - edgeL(y) + p)} ${y}`).join(" ");
/** A band that hugs her from y0 to y1; dTop/dHem bend the top and bottom edges (positive = dips in the middle) */
const hug = (y0: number, y1: number, dTop = 0, dHem = 0, p = 1) =>
  `M${f1(edgeL(y0) - p)} ${y0} Q100 ${y0 + dTop * 2} ${f1(200 - edgeL(y0) + p)} ${y0} ${downR(y0, y1, p)} L${f1(200 - edgeL(y1) + p)} ${y1} Q100 ${y1 + dHem * 2} ${f1(edgeL(y1) - p)} ${y1} ${upL(y0, y1, p)} Z`;
/** One half of a hug band, from the centre line out to her left or right side */
const half = (y0: number, y1: number, side: "L" | "R", p = 1) => side === "L"
  ? `M100 ${y0} L${f1(edgeL(y0) - p)} ${y0} ${downL(y0, y1, p)} L${f1(edgeL(y1) - p)} ${y1} L100 ${y1} Z`
  : `M100 ${y0} L${f1(200 - edgeL(y0) + p)} ${y0} ${downR(y0, y1, p)} L${f1(200 - edgeL(y1) + p)} ${y1} L100 ${y1} Z`;
/** A tank or halter in one piece: neck point, shoulder point, armpit, then hugging her sides down to the hem */
const tank = (o: { nx: number; ny?: number; sx: number; sy?: number; arm?: number; y1: number; hem?: number; neck: number; p?: number }) => {
  const { nx, ny = 89, sx, sy = 90, arm = 106, y1, hem = 1.5, neck, p = 1 } = o;
  return `M${nx} ${ny} L${sx} ${sy} L${f1(edgeL(arm) - p)} ${arm} ${downL(arm, y1, p)} L${f1(edgeL(y1) - p)} ${y1} Q100 ${y1 + hem * 2} ${f1(200 - edgeL(y1) + p)} ${y1} ${upR(arm, y1, p)} L${f1(200 - edgeL(arm) + p)} ${arm} L${200 - sx} ${sy} L${200 - nx} ${ny} Q100 ${neck} ${nx} ${ny} Z`;
};
/** Sweetheart neckline that hugs her down to y1 */
const sweetheart = (y0: number, y1: number, hem = 1.5, p = 1) =>
  `M${f1(edgeL(y0) - p)} ${y0} Q90 ${y0 - 8} 100 ${y0} Q110 ${y0 - 8} ${f1(200 - edgeL(y0) + p)} ${y0} ${downR(y0, y1, p)} L${f1(200 - edgeL(y1) + p)} ${y1} Q100 ${y1 + hem * 2} ${f1(edgeL(y1) - p)} ${y1} ${upL(y0, y1, p)} Z`;
/** A soft scalloped lace edge along a curve (drawn as a line, so it never gets a heavy outline) */
const laceEdge = (x0: number, x1: number, y: number, sag: number, colour: string, n = 12) => {
  let d = `M${x0} ${y}`;
  for (let i = 0; i < n; i++) {
    const xa = x0 + ((x1 - x0) * i) / n, xb = x0 + ((x1 - x0) * (i + 1)) / n;
    const ya = y + Math.sin((i / n) * Math.PI) * sag, yb = y + Math.sin(((i + 1) / n) * Math.PI) * sag;
    d += ` Q${f1((xa + xb) / 2)} ${f1((ya + yb) / 2 + 2.4)} ${f1(xb)} ${f1(yb)}`;
  }
  return `<path fill="none" style="stroke:${colour};stroke-width:1.1;stroke-linecap:round" d="${d}"/>`;
};

